<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import {analytics,analyticsReady,analyticsBusy,analyticsError,analyticsSupported,chooseAnalytics,deleteAnalytics,refreshAnalytics} from '../composables/analytics';
const props=defineProps<{prompt?:boolean}>();const confirming=ref(false);let timer:ReturnType<typeof setInterval>;
onMounted(()=>{timer=setInterval(()=>{if(analytics.value.deletePending)void refreshAnalytics()},3000)});onUnmounted(()=>clearInterval(timer));
</script>
<template><section v-if="analyticsSupported()&&analyticsReady&&(!props.prompt||analytics.choice==='unset')" class="analytics-card" aria-label="匿名使用统计">
<div class="analytics-head"><strong>{{props.prompt?'一起改进邯院通':'匿名使用统计'}}</strong><span v-if="!props.prompt">{{analytics.choice==='on'?'已开启':analytics.choice==='off'?'已关闭':'尚未选择'}}</span></div>
<p>仅统计活跃设备、应用版本和功能使用次数。使用随机安装标识，不上传学号、密码、课程、余额或订单。你可以随时关闭。</p>
<div v-if="props.prompt||analytics.choice==='unset'" class="analytics-actions"><button class="primary" :disabled="analyticsBusy||analytics.deletePending" @click="chooseAnalytics(true)">允许匿名统计</button><button class="text-button" :disabled="analyticsBusy" @click="chooseAnalytics(false)">暂不参与</button></div>
<template v-else><label class="analytics-switch"><span>参与匿名统计</span><input type="checkbox" aria-label="参与匿名统计" :checked="analytics.choice==='on'" :disabled="analyticsBusy||analytics.deletePending" @change="chooseAnalytics(($event.target as HTMLInputElement).checked)"/></label><p class="analytics-small">每日汇总统计近 90 天，过期明细随后续上报清理；匿名设备记录用于累计统计。关闭后不再记录和上报新使用情况，已有记录可在下方删除。</p><button v-if="!confirming&&!analytics.deletePending" class="text-button" :disabled="analyticsBusy" @click="confirming=true">删除已上报记录</button><div v-if="confirming" class="analytics-actions"><span>同时关闭统计？</span><button class="text-button" @click="deleteAnalytics();confirming=false">确认删除</button><button class="text-button" @click="confirming=false">取消</button></div><p v-if="analytics.deletePending" role="status">已关闭统计，正在请求删除。离线时会保留请求并在下次联网重试。</p><button v-if="analytics.deletePending" class="text-button" :disabled="analyticsBusy" @click="deleteAnalytics">重试删除</button></template>
<p v-if="analyticsError" role="alert">{{analyticsError}}</p></section></template>
<style scoped>.analytics-card{margin:14px 0;padding:16px;border:1px solid var(--color-border,#dde4ef);border-radius:16px;background:var(--color-surface,#fff)}.analytics-head{display:flex;justify-content:space-between;gap:12px;font-size:14px}.analytics-head span{font-size:12px;color:var(--color-muted)}.analytics-card p{font-size:12px;color:var(--color-muted);line-height:1.7;margin:10px 0}.analytics-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.analytics-actions button{min-height:40px;padding:8px 14px}.analytics-switch{display:flex;align-items:center;justify-content:space-between;min-height:44px;font-size:13px}.analytics-switch input{width:22px;height:22px;accent-color:#3158ba}.analytics-small{font-size:11px!important}</style>
